create table if not exists public.geo_countries (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  name text not null,
  sort_order integer not null default 0,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

create table if not exists public.geo_cities (
  id uuid primary key default gen_random_uuid(),
  country_id uuid not null references public.geo_countries(id) on delete cascade,
  name text not null,
  sort_order integer not null default 0,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  unique (country_id, name)
);

create index if not exists geo_countries_name_idx on public.geo_countries(name);
create index if not exists geo_countries_active_sort_idx on public.geo_countries(is_active, sort_order, name);
create index if not exists geo_cities_country_active_sort_idx on public.geo_cities(country_id, is_active, sort_order, name);
create index if not exists geo_cities_name_idx on public.geo_cities(name);

alter table public.geo_countries enable row level security;
alter table public.geo_cities enable row level security;

drop policy if exists "geo_countries_public_read" on public.geo_countries;
create policy "geo_countries_public_read"
  on public.geo_countries
  for select
  to anon, authenticated
  using (is_active = true);

drop policy if exists "geo_cities_public_read" on public.geo_cities;
create policy "geo_cities_public_read"
  on public.geo_cities
  for select
  to anon, authenticated
  using (is_active = true);

grant select on public.geo_countries to anon, authenticated;
grant select on public.geo_cities to anon, authenticated;

