insert into public.geo_cities (country_id, name, sort_order, is_active)
select countries.id, seed.name, seed.sort_order, seed.is_active
from city_seed seed
join public.geo_countries countries on countries.code = seed.country_code
on conflict (country_id, name) do update
set sort_order = excluded.sort_order,
    is_active = excluded.is_active;
